package in.finseq.insurance;

import android.app.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.os.*;import android.text.InputType;import android.view.*;import android.widget.*;import org.json.*;import java.net.URLEncoder;

public class UccOnboardingActivity extends FinseqActivity{
 LinearLayout root,body,stepBody;TextView progress;String generated="";int step=1,draftId=0;
 EditText pan,first,middle,last,dob,mobile,email,secondFirst,secondLast,secondDob,secondPan,secondEmail,secondMobile,guardianFirst,guardianLast,guardianDob,guardianPan;
 EditText bank,ifsc,cheque,address1,address2,address3,city,pincode,ckyc;Spinner gender,tax,holding,occupation,kycType,accountType,state,aadhaar;TextView kycStatus,ifscStatus;
 final String[] TAX={"01 - Individual","02 - On Behalf of Minor","03 - HUF","04 - Company","05 - AOP","06 - Partnership Firm","07 - Body Corporate","08 - Trust","09 - Society","10 - Others","11 - NRI-Others","12 - DFI","13 - Sole Proprietorship","21 - NRI Repatriable (NRE)","22 - OCB","23 - FII","24 - NRI Repatriable (NRO)","25 - Overseas Corp. Body - Others","26 - NRI Child","27 - NRI HUF (NRO)","28 - NRI Minor (NRO)","29 - NRI HUF (NRE)","31 - Provident Fund","32 - Super Annuation Fund","33 - Gratuity Fund","34 - Pension Fund","36 - Mutual Funds FOF Schemes","37 - NPS Trust","38 - Global Development Network","39 - FCRA","41 - QFI Individual","42 - QFI Minors","43 - QFI Corporate","44 - QFI Pension Funds","45 - QFI Hedge Funds","46 - QFI Mutual Funds","47 - LLP","48 - Non-Profit Organization (NPO)","51 - Public Limited Company","52 - Private Limited Company","53 - Unlisted Company","54 - Mutual Funds","55 - FPI Category I","56 - FPI Category II","57 - FPI Category III","58 - Financial Institutions","59 - Body of Individuals","60 - Insurance Company","61 - OCI Repatriation","62 - OCI Non Repatriation","70 - Person of Indian Origin","72 - Government Body","73 - Defence Establishment","74 - Non-Government Organisation","75 - Bank / Co-operative Bank","76 - Artificial Juridical Person","77 - Seafarer NRE","78 - Seafarer NRO","79 - Local Authority"};
 final String[] STATES={"UP - Uttar Pradesh","DL - Delhi","AN - Andaman & Nicobar","AP - Andhra Pradesh","AR - Arunachal Pradesh","AS - Assam","BR - Bihar","CG - Chhattisgarh","CH - Chandigarh","DD - Daman & Diu","DN - Dadra and Nagar Haveli","GA - Goa","GJ - Gujarat","HP - Himachal Pradesh","HR - Haryana","JH - Jharkhand","JK - Jammu & Kashmir","KA - Karnataka","KL - Kerala","LD - Lakshadweep","MH - Maharashtra","ML - Meghalaya","MN - Manipur","MP - Madhya Pradesh","MZ - Mizoram","NL - Nagaland","OR - Orissa","PB - Punjab","PY - Pondicherry","RJ - Rajasthan","SK - Sikkim","TN - Tamil Nadu","TE - Telangana","TR - Tripura","UA - Uttarakhand","WB - West Bengal","XX - Others"};
 @Override public void onCreate(Bundle b){super.onCreate(b);root=Ui.column(this);Ui.appHeader(root,this,"Create NSE UCC");body=Ui.contentColumn(this);root.addView(body);body.addView(Ui.text(this,"Create NSE UCC",24,true));body.addView(Ui.sub(this,"KYC → Investor → Bank → Review"));progress=Ui.sub(this,"");body.addView(progress);stepBody=Ui.card(this);body.addView(stepBody);setContentView(Ui.scroll(this,root));loadNext();}
 void loadNext(){Ui.run(this,()->{try{JSONObject j=ApiClient.get(this,"/api/v2/mf/ucc/next");generated=j.getString("ucc");Ui.ui(this,this::renderStep);}catch(Exception e){Ui.ui(this,()->Ui.toast(this,e.getMessage()));}});}
 void renderStep(){progress.setText("Step "+step+" of 4  ·  "+(step==1?"KYC":step==2?"Investor":step==3?"Bank":"Review"));stepBody.removeAllViews();if(step==1)stepKyc();else if(step==2)stepInvestor();else if(step==3)stepBank();else stepReview();}
 void generatedHeader(){stepBody.addView(Ui.label(this,"GENERATED UCC"));TextView code=Ui.text(this,generated,26,true);code.setGravity(Gravity.CENTER);code.setBackground(Ui.round(Color.rgb(236,253,245),14));code.setPadding(0,Ui.dp(this,12),0,Ui.dp(this,12));stepBody.addView(code);stepBody.addView(Ui.sub(this,"Auto Generated · Centralized serial · Manual editing disabled"));}
 Spinner sp(String[] a){Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,a));return s;}
 EditText in(String h){return Ui.input(this,h);}
 void stepKyc(){generatedHeader();pan=pan==null?in("PAN"):pan;stepBody.addView(pan);Button verify=Ui.greenButton(this,"Verify KYC");stepBody.addView(verify);kycStatus=kycStatus==null?Ui.sub(this,"Enter PAN and tap Verify KYC"):kycStatus;stepBody.addView(kycStatus);first=first==null?in("First Name (KYC auto-filled)"):first;middle=middle==null?in("Middle Name"):middle;last=last==null?in("Last Name"):last;dob=dob==null?in("DOB DD/MM/YYYY"):dob;stepBody.addView(first);stepBody.addView(middle);stepBody.addView(last);stepBody.addView(dob);if(gender==null)gender=sp(new String[]{"M - Male","F - Female","O - Other","T - Transgender"});stepBody.addView(Ui.label(this,"Gender"));stepBody.addView(gender);if(tax==null)tax=sp(TAX);stepBody.addView(Ui.label(this,"Tax Status"));stepBody.addView(tax);if(holding==null)holding=sp(new String[]{"SI - Single","JO - Joint","AS - Anyone or Survivor"});stepBody.addView(Ui.label(this,"Mode of Holding"));stepBody.addView(holding);Button holder=Ui.outlineButton(this,"Second Holder / Guardian Details");holder.setOnClickListener(v->extraHolders());stepBody.addView(holder);Button next=Ui.greenButton(this,"Continue to Investor →");next.setOnClickListener(v->{step=2;renderStep();});stepBody.addView(next);verify.setOnClickListener(v->checkKyc());}
 void extraHolders(){LinearLayout wrap=new LinearLayout(this);wrap.setOrientation(LinearLayout.VERTICAL);String taxCode=code(tax),hold=code(holding);if(hold.equals("JO")||hold.equals("AS")){wrap.addView(Ui.text(this,"Second Holder",16,true));secondFirst=secondFirst==null?in("Second holder first name"):secondFirst;secondLast=secondLast==null?in("Second holder last name"):secondLast;secondDob=secondDob==null?in("Second holder DOB DD/MM/YYYY"):secondDob;secondPan=secondPan==null?in("Second holder PAN"):secondPan;secondEmail=secondEmail==null?in("Second holder email"):secondEmail;secondMobile=secondMobile==null?in("Second holder mobile"):secondMobile;wrap.addView(secondFirst);wrap.addView(secondLast);wrap.addView(secondDob);wrap.addView(secondPan);wrap.addView(secondEmail);wrap.addView(secondMobile);}if(taxCode.equals("02")){wrap.addView(Ui.text(this,"Guardian",16,true));guardianFirst=guardianFirst==null?in("Guardian first name"):guardianFirst;guardianLast=guardianLast==null?in("Guardian last name"):guardianLast;guardianDob=guardianDob==null?in("Guardian DOB DD/MM/YYYY"):guardianDob;guardianPan=guardianPan==null?in("Guardian PAN"):guardianPan;wrap.addView(guardianFirst);wrap.addView(guardianLast);wrap.addView(guardianDob);wrap.addView(guardianPan);}if(wrap.getChildCount()==0)wrap.addView(Ui.sub(this,"Second holder/guardian is not required for the selected tax status and holding mode."));new AlertDialog.Builder(this).setTitle("Holder Details").setView(wrap).setPositiveButton("Done",null).show();}
 void stepInvestor(){mobile=mobile==null?in("Mobile"):mobile;email=email==null?in("Email"):email;address1=address1==null?in("Address 1"):address1;address2=address2==null?in("Address 2"):address2;address3=address3==null?in("Address 3"):address3;city=city==null?in("City"):city;pincode=pincode==null?in("Pincode"):pincode;if(occupation==null)occupation=sp(new String[]{"01 - Business","02 - Services","03 - Professional","04 - Agriculture","05 - Retired","06 - Housewife","07 - Student","08 - Others"});if(kycType==null)kycType=sp(new String[]{"K - KRA Compliant","C - CKYC Compliant","B - Biometric KYC","E - Aadhaar eKYC PAN"});ckyc=ckyc==null?in("CKYC Number (if applicable)"):ckyc;if(state==null)state=sp(STATES);if(aadhaar==null)aadhaar=sp(new String[]{"Y - Yes","N - No"});stepBody.addView(mobile);stepBody.addView(email);stepBody.addView(Ui.label(this,"Occupation"));stepBody.addView(occupation);stepBody.addView(Ui.label(this,"KYC Type"));stepBody.addView(kycType);stepBody.addView(ckyc);stepBody.addView(address1);stepBody.addView(address2);stepBody.addView(address3);stepBody.addView(city);stepBody.addView(Ui.label(this,"State"));stepBody.addView(state);stepBody.addView(pincode);stepBody.addView(Ui.label(this,"Aadhaar Updated"));stepBody.addView(aadhaar);navButtons(1,3);}
 void stepBank(){bank=bank==null?in("Bank account number"):bank;ifsc=ifsc==null?in("IFSC"):ifsc;cheque=cheque==null?in("Cheque / Account Holder Name"):cheque;if(accountType==null)accountType=sp(new String[]{"SB - Savings","CB - Current","NE - NRE","NO - NRO"});stepBody.addView(Ui.label(this,"Bank Account Type"));stepBody.addView(accountType);stepBody.addView(bank);stepBody.addView(ifsc);Button verify=Ui.button(this,"Verify IFSC");stepBody.addView(verify);ifscStatus=ifscStatus==null?Ui.sub(this,"IFSC not verified"):ifscStatus;stepBody.addView(ifscStatus);stepBody.addView(cheque);navButtons(2,4);verify.setOnClickListener(v->checkIfsc());}
 void navButtons(int prev,int next){LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);Button back=Ui.outlineButton(this,"← Back");Button go=Ui.greenButton(this,next==4?"Review Application →":"Continue →");row.addView(back,new LinearLayout.LayoutParams(0,-2,1));row.addView(go,new LinearLayout.LayoutParams(0,-2,1));back.setOnClickListener(v->{step=prev;renderStep();});go.setOnClickListener(v->{step=next;renderStep();});stepBody.addView(row);}
 void stepReview(){generatedHeader();stepBody.addView(Ui.text(this,"Investor",16,true));stepBody.addView(Ui.sub(this,val(first)+" "+val(middle)+" "+val(last)+" · PAN "+val(pan)+" · DOB "+val(dob)));stepBody.addView(Ui.sub(this,"Tax: "+selected(tax)+" · Holding: "+selected(holding)));stepBody.addView(Ui.text(this,"Contact & Address",16,true));stepBody.addView(Ui.sub(this,val(mobile)+" · "+val(email)));stepBody.addView(Ui.sub(this,val(address1)+", "+val(city)+", "+selected(state)+" - "+val(pincode)));stepBody.addView(Ui.text(this,"Bank",16,true));stepBody.addView(Ui.sub(this,selected(accountType)+" · "+val(bank)+" · "+val(ifsc)));CheckBox details=new CheckBox(this);details.setText("I have verified PAN, bank and investor details.");CheckBox live=new CheckBox(this);live.setText("I consent to create this UCC on NSE Invest LIVE.");stepBody.addView(details);stepBody.addView(live);Button draft=Ui.greenButton(this,"Validate & Reserve UCC");stepBody.addView(draft);Button back=Ui.outlineButton(this,"← Back to Bank");back.setOnClickListener(v->{step=3;renderStep();});stepBody.addView(back);draft.setOnClickListener(v->{if(!details.isChecked()||!live.isChecked()){Ui.toast(this,"Tick both consent boxes");return;}createDraft();});}
 String val(EditText e){return e==null?"":e.getText().toString().trim();}String selected(Spinner s){return s==null?"":String.valueOf(s.getSelectedItem());}String code(Spinner s){String x=selected(s);int p=x.indexOf(' ');return p>0?x.substring(0,p):x;}
 void checkKyc(){Ui.run(this,()->{try{JSONObject j=ApiClient.post(this,"/api/v2/mf/kyc-check",new JSONObject().put("pan",val(pan)));Ui.ui(this,()->{String nm=j.optString("name");if(!nm.isEmpty()){String[] p=nm.trim().split("\\s+");first.setText(p.length>0?p[0]:"");last.setText(p.length>1?p[p.length-1]:"");if(p.length>2){StringBuilder m=new StringBuilder();for(int i=1;i<p.length-1;i++){if(m.length()>0)m.append(' ');m.append(p[i]);}middle.setText(m.toString());}first.setEnabled(false);middle.setEnabled(false);last.setEnabled(false);}kycStatus.setText(j.optString("decision")+" · "+j.optString("remark"));kycStatus.setTextColor(j.optString("decision").toUpperCase().contains("ELIGIBLE")?Ui.GREEN:Ui.AMBER);});}catch(Exception e){Ui.ui(this,()->Ui.toast(this,e.getMessage()));}});}
 void checkIfsc(){Ui.run(this,()->{try{JSONObject j=ApiClient.get(this,"/api/v2/mf/ifsc-check?ifsc="+URLEncoder.encode(val(ifsc),"UTF-8"));Ui.ui(this,()->ifscStatus.setText(j.optString("bank")+" · "+j.optString("branch")+" · "+j.optString("address")));}catch(Exception e){Ui.ui(this,()->Ui.toast(this,e.getMessage()));}});}
 JSONObject payload()throws Exception{JSONObject f=new JSONObject();f.put("primary_holder_first_name",val(first));f.put("primary_holder_middle_name",val(middle));f.put("primary_holder_last_name",val(last));f.put("primary_holder_pan",val(pan));f.put("primary_holder_dob_incorporation",val(dob));f.put("gender",code(gender));f.put("tax_status",code(tax));f.put("holding_nature",code(holding));f.put("occupation_code",code(occupation));f.put("indian_mobile_no",val(mobile));f.put("email",val(email));f.put("primary_holder_kyc_type",code(kycType));f.put("primary_holder_ckyc_number",val(ckyc));f.put("account_type_1",code(accountType));f.put("account_no_1",val(bank));f.put("ifsc_code_1",val(ifsc));f.put("cheque_name",val(cheque));f.put("address_1",val(address1));f.put("address_2",val(address2));f.put("address_3",val(address3));f.put("city",val(city));f.put("state",code(state));f.put("pincode",val(pincode));f.put("aadhaar_updated",code(aadhaar));if(secondFirst!=null){f.put("second_holder_first_name",val(secondFirst));f.put("second_holder_last_name",val(secondLast));f.put("second_holder_dob",val(secondDob));f.put("second_holder_pan",val(secondPan));f.put("second_holder_email",val(secondEmail));f.put("second_holder_mobile",val(secondMobile));f.put("second_holder_kyc_type","K");}if(guardianFirst!=null){f.put("guardian_first_name",val(guardianFirst));f.put("guardian_last_name",val(guardianLast));f.put("guardian_dob",val(guardianDob));f.put("guardian_pan",val(guardianPan));f.put("guardian_kyc_type","K");f.put("guardian_relation","13");}return f;}
 void createDraft(){Ui.run(this,()->{try{JSONObject j=ApiClient.post(this,"/api/v2/mf/ucc/draft",payload());draftId=j.getInt("draft_id");String u=j.optString("ucc",generated);Ui.ui(this,()->submitDraft(u));}catch(Exception e){Ui.ui(this,()->Ui.toast(this,e.getMessage()));}});}
 void submitDraft(String u){Ui.run(this,()->{try{JSONObject j=ApiClient.post(this,"/api/v2/mf/ucc/drafts/"+draftId+"/submit",new JSONObject().put("confirm_details",true).put("confirm_live",true));Ui.ui(this,()->showAuthorization(j.optString("ucc",u)));}catch(Exception e){Ui.ui(this,()->Ui.toast(this,e.getMessage()));}});}
 void showAuthorization(String ucc){Ui.run(this,()->{try{JSONObject j=ApiClient.get(this,"/api/v2/mf/ucc/"+URLEncoder.encode(ucc,"UTF-8")+"/authorization");Ui.ui(this,()->{stepBody.removeAllViews();progress.setText("UCC Created · Authorization");stepBody.addView(Ui.text(this,ucc,26,true));JSONObject a=j.optJSONObject("authorization"),b=j.optJSONObject("bank");stepBody.addView(Ui.text(this,"Authorization: "+(a==null?"Pending":a.optString("status","Pending")),16,true));stepBody.addView(Ui.sub(this,"Bank validation: "+(b==null?"Pending":b.optString("status","Pending"))));if(a!=null){JSONObject links=a.optJSONObject("links");if(links!=null&&!links.optString("first").isEmpty()){Button auth=Ui.greenButton(this,"Authorize Now");auth.setOnClickListener(v->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(links.optString("first")))));stepBody.addView(auth);}}Button refresh=Ui.button(this,"Check Authorization & Bank Status");refresh.setOnClickListener(v->showAuthorization(ucc));stepBody.addView(refresh);Button done=Ui.outlineButton(this,"Back to Mutual Fund Dashboard");done.setOnClickListener(v->{startActivity(new Intent(this,InvestActivity.class));finish();});stepBody.addView(done);});}catch(Exception e){Ui.ui(this,()->Ui.toast(this,e.getMessage()));}});}
}
